def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated frame is color 5; the embedded rectangular pattern is
    # represented by the non-frame colors at the intersections of its rails.
    # Here the two horizontal rails and two side rails enclose one cell.
    # Read its interior, which is the dominant color inside the frame.
    interior = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 5:
                interior.append(grid[r][c])
    if not interior:
        return [[0]]
    from collections import Counter
    return [[Counter(interior).most_common(1)[0][0]]]
