def transform(grid):
    # The grid is a single marked rectangle: the two colored endpoints on
    # each horizontal separator encode its value.
    h, w = len(grid), len(grid[0])
    for r in range(h):
        vals = [v for v in grid[r] if v != 5]
        if len(vals) >= 2 and len(set(vals)) == 1 and vals[0] != 0:
            return [[vals[0]]]
    return [[0]]
